 describe('api.js', () => {
   beforeEach(() => {
     localStorage.clear();
     globalThis.fetch = vi.fn(async () => ({ ok: true, json: async () => [] }));
   });

   afterEach(() => {
     vi.restoreAllMocks();
   });

   it('tem os 10 usuários da seção 4 do contrato', () => {
